"""Generate a standalone, read-only UI review of the 50-topic roadmap (not the Next.js app)."""
import re, json, html
from pathlib import Path
root=Path(__file__).resolve().parent.parent
source=(root/'components/junior/master-roadmap.ts').read_text()
records=json.loads(source.split('export const MASTER_ROADMAP: RoadmapTopic[] = ',1)[1].rsplit(';',1)[0])
css=(root/'components/junior/hands-on.css').read_text()
base='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OpenLab Junior 50-Topic Atlas · Standalone Layout Preview</title><style>body{margin:0;background:#08162a;font-family:Inter,system-ui,Arial,sans-serif;color:#f7fcff}button,input{font:inherit}</style><style>__CSS__</style></head><body><main class="roadmap-root"><header class="roadmap-hero"><span class="roadmap-overline">JR. OPENLAB · 50-TOPIC SCIENCE CURRICULUM</span><h1>From the first atom to advanced life science.</h1><p>Every topic and learning objective from the supplied blueprint, organized as a progressive Class 9–12 path. Only linked working labs are marked as available in the full product.</p><div class="roadmap-numbers"><span><b>25</b> Chemistry topics</span><span><b>25</b> Biology topics</span><span><b>4</b> learning levels</span></div></header><div class="roadmap-toolbar"><div id="subjects" class="roadmap-subjects" aria-label="Filter subject"></div><label class="roadmap-search">⌕ <input id="search" type="search" placeholder="Find quantum, titration, genetics…" aria-label="Search topics"></label></div><div class="roadmap-grades" id="grades"></div><div class="roadmap-layout"><section class="roadmap-list"><div class="roadmap-listHeader"><b id="count">50 topics</b><span>Original specification · learning objectives</span></div><div id="items"></div></section><article id="roadmap-detail" class="roadmap-detail"></article></div></main><script>const TOPICS=__DATA__;const RELATED=new Set([1,2,3,4,6,7,8,10,11,13,15,18,20,21,22,24,26,27,30,31,33,34,38,39,44,45,49]);const BUILT=new Set([1,15,24,26]);let subj='all',grade=0,sel=1,query='';const el=id=>document.getElementById(id);function safe(t){return String(t).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));}function btn(title,fn,active,small){const x=document.createElement('button');x.textContent=title;x.className=active?'active':'';if(small){const tag=document.createElement('small');tag.textContent=small;x.append(tag)}x.onclick=fn;return x;}function render(){el('subjects').replaceChildren(...[['all','All science'],['chemistry','⚗ Chemistry'],['biology','◉ Biology']].map(([v,label])=>btn(label,()=>{subj=v;render()},subj===v)));el('grades').replaceChildren(...[0,9,10,11,12].map(g=>btn(g?'Class '+g:'All classes',()=>{grade=g;render()},grade===g)));const found=TOPICS.filter(t=>(subj==='all'||t.subject===subj)&&(!grade||t.grade===grade)&&(t.title+' '+t.objective+' '+t.experience).toLowerCase().includes(query.toLowerCase()));el('count').textContent=found.length+' topics';el('items').replaceChildren(...found.map(t=>{const x=document.createElement('button');x.className='roadmap-topic'+(sel===t.number?' selected':'');const n=document.createElement('span');n.className='roadmap-topicNumber '+t.subject;n.textContent=String(t.number).padStart(2,'0');const d=document.createElement('div'),m=document.createElement('small'),a=document.createElement('strong'),p=document.createElement('p');m.textContent=t.subject.toUpperCase()+' / CLASS '+t.grade;a.textContent=t.title;p.textContent=t.objective;d.append(m,a,p);const arrow=document.createElement('span');arrow.className='roadmap-topicArrow';arrow.textContent='↗';x.append(n,d,arrow);x.onclick=()=>{sel=t.number;render()};return x;}));const t=TOPICS.find(t=>t.number===sel),detail=el('roadmap-detail');detail.innerHTML='<div class="roadmap-detailIntro"><span>TOPIC '+String(t.number).padStart(2,'0')+' / CLASS '+t.grade+'</span><span>'+t.subject.toUpperCase()+'</span></div><h2>'+safe(t.title)+'</h2><div class="roadmap-detailSection"><h3>Proposed hands-on experience</h3><p>'+safe(t.experience)+'</p></div><div class="roadmap-detailSection objective"><h3>Learning outcome</h3><p>'+safe(t.objective)+'</p></div><div class="roadmap-availability"><b>'+(BUILT.has(t.number)?'Dedicated workbench in full application':RELATED.has(t.number)?'Related lab in full application':'Planned · not implemented')+'</b><p>Standalone preview only. Open the installed OpenLab Junior app to operate the real experiments.</p></div>';}el('search').oninput=e=>{query=e.target.value;render()};render();</script></body></html>'''
base=base.replace('__CSS__',css).replace('__DATA__',json.dumps(records,ensure_ascii=False).replace('</','<\\/'))
out=root/'demo/roadmap-preview.html';out.write_text(base,encoding='utf8')
print('Standalone roadmap preview:',out)
